package com.fasterxml.jackson.databind.node;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonToken;
import com.fasterxml.jackson.core.base.ParserMinimalBase;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.node.IntNode;
import com.fasterxml.jackson.databind.node.NumericNode;
import com.fasterxml.jackson.databind.node.TextNode;
import java.io.*;
import java.io.IOException;
import java.io.OutputStream;
import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.junit.*;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class TreeTraversingParser_getIntValue_TriageGen0Test {

    private ObjectMapper mapper;
    private JsonNode rootNode;
    private TreeTraversingParser parser;

    @Before
    public void setUp() {
        mapper = new ObjectMapper();
        rootNode = mapper.createObjectNode();
    }

    /**
     * Helper to instantiate TreeTraversingParser via reflection or constructor 
     * and inject the protected currentNumericNode state via reflection if necessary.
     * Since currentNumericNode() is protected and depends on internal state, 
     * we mock the behavior by controlling the internal node.
     */
    private TreeTraversingParser createParserWithNode(NumericNode node) throws Exception {
        TreeTraversingParser parser = new TreeTraversingParser(rootNode);

        // Use reflection to set the internal state that currentNumericNode() relies on.
        // In Jackson's TreeTraversingParser, currentNumericNode typically returns 
        // the node at the current parser position.
        // Since we cannot easily move the parser pointer without a full stream, 
        // we mock the parser or use a spy to override currentNumericNode.
        TreeTraversingParser spyParser = spy(parser);
        doReturn(node).when(spyParser).currentNumericNode();
        return spyParser;
    }

    @Test
    public void testGetIntValue_Success() throws Exception {
        // Arrange
        IntNode intNode = mapper.getNodeFactory().numberNode(123);
        TreeTraversingParser parser = createParserWithNode(intNode);

        // Act
        int result = parser.getIntValue();

        // Assert
        Assert.assertEquals(123, result);
        verify(parser, times(1)).currentNumericNode();
    }

    @Test
    public void testGetIntValue_NegativeValue() throws Exception {
        // Arrange
        IntNode intNode = mapper.getNodeFactory().numberNode(-456);
        TreeTraversingParser parser = createParserWithNode(intNode);

        // Act
        int result = parser.getIntValue();

        // Assert
        Assert.assertEquals(-456, result);
    }

    @Test
    public void testGetIntValue_LargeValue() throws Exception {
        // Arrange
        // Using a value that fits in int but is large
        IntNode intNode = mapper.getNodeFactory().numberNode(Integer.MAX_VALUE);
        TreeTraversingParser parser = createParserWithNode(intNode);

        // Act
        int result = parser.getIntValue();

        // Assert
        Assert.assertEquals(Integer.MAX_VALUE, result);
    }

    @Test(expected = ClassCastException.class)
    public void testGetIntValue_ThrowsClassCastException_WhenNotNumeric() throws Exception {
        // Arrange
        // currentNumericNode() is expected to return a NumericNode. 
        // If it returns a non-numeric node (like TextNode) via a mock/hack, 
        // the cast (NumericNode) currentNumericNode() will fail.
        TextNode textNode = mapper.getNodeFactory().textNode("not a number");

        TreeTraversingParser parser = spy(new TreeTraversingParser(rootNode));
        doReturn(textNode).when(parser).currentNumericNode();

        // Act
        parser.getIntValue();
    }

    @Test(expected = IOException.class)
    public void testGetIntValue_ThrowsIOException_WhenCurrentNumericNodeFails() throws Exception {
        // Arrange
        TreeTraversingParser parser = spy(new TreeTraversingParser(rootNode));
        doThrow(new IOException("Simulated IO error")).when(parser).currentNumericNode();

        // Act
        parser.getIntValue();
    }
}
